(function() {
  const tooltipEl = element.querySelector('[data-tooltip-id="horoscope-dropdown"]');
  const linkEl = element.querySelector('a[data-ylk*="subsec:horoscope"]');
  if (tooltipEl || linkEl) {
    element.style.display = 'none';
  }
})();

(function() {
  const HARD_NEWS_CATEGORIES = ['politics', 'world', 'u.s.', 'us', 'news', 'business', 'science', 'health'];

  const items = Array.from(element.children).filter(li => {
    return li.classList.contains('list-none') || li.classList.contains('border-tertiary');
  });

  if (items.length === 0) return;

  function getCategoryText(li) {
    const labelEl = li.querySelector('.label-m-emphasized');
    if (labelEl) {
      return labelEl.textContent.trim().toLowerCase();
    }
    const dataYga = li.querySelector('a[data-yga]');
    if (dataYga) {
      try {
        const parsed = JSON.parse(dataYga.getAttribute('data-yga'));
        if (parsed && parsed.yContentCategory) {
          return parsed.yContentCategory.toLowerCase();
        }
      } catch(e) {}
    }
    return '';
  }

  function isHardNews(categoryText) {
    return HARD_NEWS_CATEGORIES.some(cat => categoryText.includes(cat));
  }

  const hardNewsItems = [];
  const otherItems = [];

  items.forEach(li => {
    const cat = getCategoryText(li);
    if (isHardNews(cat)) {
      hardNewsItems.push(li);
    } else {
      otherItems.push(li);
    }
  });

  const allOrdered = hardNewsItems.concat(otherItems);

  element.innerHTML = '';
  allOrdered.forEach(li => element.appendChild(li));
})();
